import { mergeClasses } from '@griffel/react';
import { useMemo } from 'react';
export function useMergeAllClasses(classNamesBySlots1, classNamesBySlots2) {
    const classNames = useMemo(() => {
        const keys = [
            ...new Set([
                ...Object.keys(classNamesBySlots1 ?? {}),
                ...Object.keys(classNamesBySlots2 ?? {}),
            ]),
        ];
        return keys.reduce((acc, cur) => {
            acc[cur] = mergeClasses(classNamesBySlots1?.[cur], classNamesBySlots2?.[cur]);
            return acc;
        }, {});
    }, [classNamesBySlots1, classNamesBySlots2]);
    return classNames;
}
