import { useMemo } from 'react';
export function useFlexContainerStyles({ vertical = false, wrap = false, justify = 'flex-start', align = 'stretch', gap = '', style = {}, }) {
    return useMemo(() => ({
        display: 'flex',
        flexDirection: vertical ? 'column' : 'row',
        justifyContent: justify,
        alignItems: align,
        flexWrap: wrap ? 'wrap' : 'nowrap',
        ...(gap !== '' ? { gap } : {}),
        ...style,
    }), [vertical, justify, align, wrap, gap, style]);
}
